        const dy = mouse.y - y
        const dist = Math.sqrt(dx * dx + dy * dy)
        const radius = 180

        if (dist < radius && mouse.isHovered) {
          const factor = (1 - dist / radius) * (props.strength / dist) * 15
          x += dx * factor
          y += dy * factor
        }

        // 冲击波扰动
